      renwu = "npc",
      role1 = 149000,
      role2 = 101103,
      role3 = 101202,
      roleanim = 1.1,
      sentence = "In about fifth grade, I was hall monitor for the week, and I was at the school entrance checking that my fellow students coming in were all properly uniformed.",
