    },
    [44] = {
      beijing = 4826,
      dialog = 3,
      music = "lzy_15047_voice",
      renwu = "npc",
      sentence = "After two solid efforts in a row, I was starting to get on a roll, and the rest of the questions went by pretty quickly.",
