    },
    [45] = {
      beijing = 4826,
      dialog = 3,
      music = "lzy_15047_voice",
      renwu = "npc",
      sentence = "But there were only a few questions that allowed me to pry into stories from Victor's childhood. Most of them were designed to get the parents to write down their feelings and thereby deepen understanding between parent and child.",
