    [68] = {
      beijing = 4826,
      dialog = 3,
      music = "lzy_15047_voice",
      renwu = "npc",
      sentence = "I bit down indignantly on the pen and wracked my brain for ideas. Out of the corner of my eye, Victor pulled out the first page that I'd completed and was looking it over carefully.",
