    [75] = {
      beijing = 4826,
      dialog = 3,
      music = "lzy_15047_voice",
      renwu = "npc",
      sentence = "And then, perhaps at some moment, they felt a flicker of curiosity toward each other.",
      next = {76}
    },
    [76] = {
      beijing = 4826,
      dialog = 3,
      music = "lzy_15047_voice",
      renwu = "npc",
      sentence = "I picked up my pen again and earnestly wrote down the thoughts I used to keep buried deep down inside.",
