    },
    [77] = {
      beijing = 4826,
      dialog = 3,
      music = "109_LZY_Birthday_2023",
      renwu = "npc",
      sentence = "\"When I was little, I actually used to occasionally daydream that I would just so happen to pass by that school where the older boy went, and I'd see him with his backpack on, leaving school for the day.\"",
      next = {78}
    },
    [78] = {
      beijing = 4826,
      dialog = 3,
      music = "109_LZY_Birthday_2023",
      renwu = "npc",
      sentence = "\"Or during some break between classes, I'd run into him at the convenience store or the stationery store.\"",
      next = {79}
    },
    [79] = {
      beijing = 4826,
      dialog = 3,
      music = "109_LZY_Birthday_2023",
      renwu = "npc",
      sentence = "\"I was so curious back then what life was like for that boy who made the yummy pudding.\"",
      next = {80}
    },
    [80] = {
      beijing = 4826,
      dialog = 3,
      music = "109_LZY_Birthday_2023",
      renwu = "npc",
      sentence = "\"Would he often play soccer on the school sports field? Perhaps he'd accidentally kick one astray and maybe break a window?\"",
      next = {81}
    },
    [81] = {
      beijing = 4826,
      dialog = 3,
      music = "109_LZY_Birthday_2023",
      renwu = "npc",
      sentence = "As the tip of the pen scratched over the paper, all of a sudden I realized that the classroom had gotten very quiet.",
