      role1 = 150000,
      role2 = 102101,
      role3 = 102203,
      role5 = 150402,
      roleanim = 1.1,
      sentence = "When I got halfway through, I put down my pen and shook my fingertips. When I looked up, I was looking straight into a tranquil gaze.",
